def simulate_energy(px: list[float], py: list[float], vx: list[float],
                    vy: list[float], mass: list[float], steps: int, dt: float) -> float:
    n: int = len(px)
    x: list[float] = []
    y: list[float] = []
    u: list[float] = []
    v: list[float] = []
    for i in range(n):
        x.append(px[i])
        y.append(py[i])
        u.append(vx[i])
        v.append(vy[i])
    for s in range(steps):
        for i in range(n):
            ax: float = 0.0
            ay: float = 0.0
            for j in range(n):
                if i != j:
                    dx: float = x[j] - x[i]
                    dy: float = y[j] - y[i]
                    d2: float = dx * dx + dy * dy + 0.01
                    inv: float = 1.0 / (d2 * (d2 ** 0.5))
                    ax += mass[j] * dx * inv
                    ay += mass[j] * dy * inv
            u[i] += ax * dt
            v[i] += ay * dt
        for i in range(n):
            x[i] += u[i] * dt
            y[i] += v[i] * dt
    kinetic: float = 0.0
    for i in range(n):
        kinetic += 0.5 * mass[i] * (u[i] * u[i] + v[i] * v[i])
    return kinetic


def monte_carlo_pi(samples: int, seed: int) -> float:
    state: int = seed % 2147483648
    inside: int = 0
    for i in range(samples):
        state = (state * 1103515245 + 12345) % 2147483648
        x: float = float(state) / 2147483648.0
        state = (state * 1103515245 + 12345) % 2147483648
        y: float = float(state) / 2147483648.0
        if x * x + y * y < 1.0:
            inside += 1
    return 4.0 * float(inside) / float(samples)


def life_generations(grid: list[list[int]], gens: int) -> int:
    h = len(grid)
    w = len(grid[0])
    cells = [row[:] for row in grid]
    for _ in range(gens):
        nxt = [[0] * w for _ in range(h)]
        for y, row in enumerate(cells):
            for x in range(w):
                total = 0
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy != 0 or dx != 0:
                            total += cells[(y + dy) % h][(x + dx) % w]
                nxt[y][x] = 1 if total == 3 or (row[x] == 1 and total == 2) else 0
        cells = nxt
    return sum(sum(row) for row in cells)

